// Human-readable, evidence-scoped assessment; scores are not generated by export checks.
import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
const root='/Users/zhengwei/Downloads/caption-saved-20260929';
const read=async name=>JSON.parse(await fs.readFile(root+'/'+name,'utf8'));
const api=async(path,body)=>{const r=await fetch('http://127.0.0.1:3000/api/footage/templates'+path,{method:body?'POST':'GET',headers:{'content-type':'application/json','x-requested-with':'moirai-footage'},body:body?JSON.stringify(body):undefined});const d=await r.json();assert.ok(r.ok,JSON.stringify(d));return d;};
const application=await read('application.json'),style=await read('style.json'),submission=await read('submission.json');
assert.deepEqual((await api('/dynamic-assets/'+style.id)).definition,style);
const item=await api('/production/'+submission.id+'/items/0');assert.equal(item.previews.length,3);
for(const p of item.previews)assert.equal(createHash('sha256').update(await fs.readFile(root+`/preview-${p.fixture}.mp4`)).digest('hex'),p.sha256);
const inspection='实际查看三份全片2fps全幅联系表、全部129词中点裁切联系表、两张英文双行全幅；另查看7段30fps连续裁切：0-0、0-4、1-0、1-1、1-3、2-0、2-5，覆盖每片首尾及长句。其余8段连续帧仅生成，未逐一查看。';
const limitations='未试听、未实时整片播放；连续检查为下方1280×240局部，完整构图是2fps抽样。中文为黑底音频，另外两例为英文采访；未验证其他画幅、极长文字、中文实拍或任意主体位置。';
const request={application,review:{templateId:item.templateId,templateRevision:item.templateRevision,batchId:submission.id,item:0,reviewer:'Codex · 清晰逐词字幕保存版视觉评审',
composition:{score:21,rationale:'两份采访的字幕避开脸，居中双行布局稳定；字幕和矩形底板仍盖住部分手势，不能视为任意人物构图适配。中文黑底只验证排版。'},
motion:{score:22,rationale:'129个词的高亮范围和实测词时间逐一对应。所看7段连续帧中无高亮导致的换行抖动或退出残留；直接切入切出较生硬，未试听节奏。'},
assets:{score:16,rationale:'细描边、轻阴影与半透明深色底板使花纹衣服背景上的白字清楚；黄字高亮可辨识，但矩形底板与排版设计基础，不能据此声称开拍同等质感。'},
adaptation:{score:16,rationale:'同一保存v1覆盖15句中文及英文、129词，长英文稳定双行；验证限于横屏两位采访与中文音频，未解决手势遮挡及更多画幅适配。'},
editability:{score:9,rationale:'保存v1原生Application直接生产，保留可编辑文字、高亮和底板；同版本已验证工作台字号草稿、跨图层选择、刷新回读与手机无溢出。内容与样式分离；本轮未重复所有编辑控件测试。'},
evidence:item.previews.map(p=>({fixture:p.fixture,sha256:p.sha256})),inspection,limitations,blockingFindings:['字幕底板仍覆盖部分手势，基础排版和切入切出需继续打磨。','未完成试听、更多画幅和中文实拍适配验收。'],listened:false}};
await fs.writeFile(root+'/style-review-request.json',JSON.stringify(request,null,2));
const receipt=await api('/dynamic-assets/reviews',request);assert.equal(receipt.total,84);assert.equal(receipt.meetsInternalThreshold,false);
const current=(await api('/dynamic-assets/reviews')).reviews.find(r=>r.id===receipt.id);assert.ok(current.current&&current.evidenceCurrent);
await fs.writeFile(root+'/style-review-receipt.json',JSON.stringify(current,null,2));
const doc=await read('inspection.json');Object.assign(doc,{inspection,limitations,score:84,reviewId:receipt.id,listened:false});await fs.writeFile(root+'/inspection.json',JSON.stringify(doc,null,2));
console.log(JSON.stringify({id:receipt.id,total:receipt.total,current:current.current,evidenceCurrent:current.evidenceCurrent}));
